SELECT 

WHERE ci.ORDER_ID = #{orderId}
ORDER BY ci.RECORD_ID

SELECT * FROM (
    SELECT t.*, ROWNUM rn FROM (
        SELECT 

        WHERE 1 = 1

            AND (o.ORDER_NO LIKE '%' || #{keyword} || '%'
              OR c.CUST_NAME LIKE '%' || #{keyword} || '%'
              OR r.ROOM_NO   LIKE '%' || #{keyword} || '%')

         AND ci.STATUS = #{status} 
         AND ci.CHECK_IN >= #{startDate} 
         AND ci.CHECK_IN <  #{endDate}   
        ORDER BY ci.RECORD_ID DESC
    ) t WHERE ROWNUM <= #{offset} + #{limit}
) WHERE rn > #{offset}

SELECT COUNT(1) FROM CHECK_IN_RECORD ci LEFT JOIN HOTEL_ORDER o ON ci.ORDER_ID = o.ORDER_ID LEFT JOIN CUSTOMER c ON o.CUSTOMER_ID = c.CUSTOMER_ID LEFT JOIN ROOM r ON ci.ROOM_ID = r.ROOM_ID WHERE 1 = 1
AND (o.ORDER_NO LIKE '%' || #{keyword} || '%' OR c.CUST_NAME LIKE '%' || #{keyword} || '%' OR r.ROOM_NO LIKE '%' || #{keyword} || '%')
AND ci.STATUS = #{status} AND ci.CHECK_IN >= #{startDate} AND ci.CHECK_IN < #{endDate}
